import sys,numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['scene_cam'],depth=True); d=o.last_depth['scene_cam']; a=o.last['scene_cam']; print('time',o.meta['time_left_s'])
for y in range(204,225):
 for x in range(372,393):
  if np.linalg.norm(a[y,x].astype(float)) < 180 and d[y,x]>0:
   print('candidate',x,y,a[y,x].tolist(),d[y,x]);
# exact map median selected. solve camera coords to world with inverse ext.
E=np.array(o.meta['cameras']['scene_cam']['extrinsic_cv']); K=np.array(o.meta['cameras']['scene_cam']['intrinsic_cv']);
for u,v in [(381,214),(380,214),(382,214),(381,215),(380,213),(320,210)]:
 z=float(np.median(d[v-2:v+3,u-2:u+3])); pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]); pw=np.linalg.inv(E[:,:3])@(pc-E[:,3]); print('xyz',u,v,'depth',z,'world',pw)
